129	  setAboutScenePlanesVisible(
130	    pageConfig: AboutPageConfig,
131	    visible: boolean,
132	  ): void {
133	    const elements = this._collectAboutScenePlaneElements(pageConfig);
134	    if (elements.length === 0) return;
135	    elements.forEach((element) => {
136	      element.style.opacity = visible ? "1" : "0";
137	      element.style.transform = visible
138	        ? "translate3d(0, 0, 0)"
139	        : "translate3d(0, 24px, 0)";
140	      element.style.pointerEvents = visible ? "" : "none";
141	      Aria.setHidden(element, !visible);
142	    });
143	  }
