145	  async revealAboutScenePlanes(
146	    pageConfig: AboutPageConfig,
147	    gsap: GsapGlobal | null,
148	  ): Promise<void> {
149	    const elements = this._collectAboutScenePlaneElements(pageConfig);
150	    if (elements.length === 0) return;
151	    if (!gsap) {
152	      this.setAboutScenePlanesVisible(pageConfig, true);
153	      return;
154	    }
155	    await new Promise<void>((resolve) => {
156	      elements.forEach((element) => {
157	        Aria.setHidden(element, false);
158	        element.style.pointerEvents = "";
159	      });
160	      gsap.to(elements, {
161	        opacity: 1,
162	        y: 0,
163	        duration: 0.72,
164	        stagger: 0.06,
165	        ease: "power3.out",
166	        onComplete: () => resolve(),
167	      });
168	    });
169	  }
