171	  waitForAboutHeroIntroClick(pageConfig: AboutPageConfig): Promise<void> {
172	    const triggerSelector = pageConfig.scrollSceneSelectors?.heroIntro;
173	    if (!triggerSelector) return Promise.resolve();
174	    const section = this._queryOne<HTMLElement>(triggerSelector);
175	    if (!section) return Promise.resolve();
176	    const trigger =
177	      section.querySelector<HTMLButtonElement>(ABOUT_HERO_INTRO_ACTION_SELECTOR);
178	    if (!trigger) return Promise.resolve();
179	    return new Promise<void>((resolve) => {
180	      const onClick = (): void => {
181	        trigger.removeEventListener("click", onClick);
182	        resolve();
183	      };
184	      trigger.addEventListener("click", onClick, { once: true });
185	    });
186	  }
