233	
234	    const nextStep = this._resolveAboutHeroSloganKeywordStep(sceneKey, progress);
235	    const shouldAnimate = sceneKey === "heroSlogan";
236	    if (
237	      this._aboutHeroSloganKeywordStep === nextStep &&
238	      shouldAnimate &&
239	      viewport.style.width.length > 0
240	    ) {
241	      return;
242	    }
243	
244	    this._aboutHeroSloganKeywordStep = nextStep;
245	    this._applyAboutHeroSloganKeywordStep(
