285	  private _collectAboutScenePlaneElements(
286	    pageConfig: AboutPageConfig,
287	  ): HTMLElement[] {
288	    const selectorValues = Object.values(pageConfig.scrollSceneSelectors ?? {});
289	    const dedupedSelectors = Array.from(
290	      new Set(selectorValues.filter((selector): selector is string => !!selector)),
291	    );
292	    return dedupedSelectors
293	      .map((selector) => this._queryOne<HTMLElement>(selector))
294	      .filter((element): element is HTMLElement => element != null);
295	  }
