297	  private _resolveAboutHeroSloganKeywordTrack(): HTMLElement | null {
298	    if (this._aboutHeroSloganKeywordTrack?.isConnected) {
299	      return this._aboutHeroSloganKeywordTrack;
300	    }
301	    this._aboutHeroSloganKeywordTrack = this._queryOne<HTMLElement>(
302	      ABOUT_HERO_SLOGAN.trackSelector,
303	    );
304	    return this._aboutHeroSloganKeywordTrack;
