306	
307	  private _resolveMainWhyShowcaseProgress(
308	    sceneKey: MainSceneSectionKey,
309	    progress: number,
310	  ): number {
311	    if (sceneKey === "whyus") {
312	      return Helpers.clamp01(progress);
313	    }
314	
315	    const sceneOrder: readonly MainSceneSectionKey[] = [
316	      "intro",
317	      "hero",
318	      "story",
319	      "who",
320	      "whyus",
321	      "services",
322	      "works",
323	      "worksDetail",
324	      "worksFinal",
325	      "client",
326	      "contact",
327	    ];
328	    const currentIndex = sceneOrder.indexOf(sceneKey);
329	    const whyIndex = sceneOrder.indexOf("whyus");
330	    if (currentIndex > whyIndex) {
331	      return 1;
332	    }
333	    return 0;
334	  }
