336	  private _resolveAboutHeroSloganKeywordViewport(): HTMLElement | null {
337	    if (this._aboutHeroSloganKeywordViewport?.isConnected) {
338	      return this._aboutHeroSloganKeywordViewport;
339	    }
340	    this._aboutHeroSloganKeywordViewport = this._queryOne<HTMLElement>(
