342	    );
343	    return this._aboutHeroSloganKeywordViewport;
344	  }
345	
346	  private _resolveAboutHeroSloganKeywordStep(
347	    sceneKey: AboutSceneSectionKey,
348	    progress: number,
349	  ): number {
350	    if (sceneKey !== "heroSlogan") return 0;
351	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
352	    const clampedProgress = Helpers.clamp01(progress);
353	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
354	      clampedProgress,
355	    );
356	    return Math.min(
357	      Math.floor(windowedProgress * keywordCount),
358	      keywordCount - 1,
359	    );
360	  }
361	
362	  private _resolveAboutHeroSloganKeywordProgress(progress: number): number {
363	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
364	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
365	    if (end <= start) return progress;
366	    if (progress <= start) return 0;
367	    if (progress >= end) return 1;
368	    return (progress - start) / (end - start);
369	  }
