371	  private _initAboutHeroSloganKeywordViewportWidth(
372	    viewport: HTMLElement,
373	    track: HTMLElement,
374	  ): void {
375	    const keywords = this._resolveAboutHeroSloganKeywordElements(track);
376	    const maxWidth = keywords.reduce((acc, kw) => {
377	      return Math.max(acc, kw.scrollWidth, kw.getBoundingClientRect().width, 1);
378	    }, 1);
379	    viewport.style.width = `${maxWidth}px`;
380	  }
381	
382	  private _applyAboutHeroSloganKeywordStep(
383	    viewport: HTMLElement,
384	    track: HTMLElement,
385	    step: number,
386	    shouldAnimate: boolean,
387	    gsap: GsapGlobal | null,
388	  ): void {
389	    const keywordHeight = this._resolveAboutHeroSloganKeywordHeight(track, step);
390	    const keywordWidth = this._resolveAboutHeroSloganKeywordWidth(track, step);
391	    const keywords = this._resolveAboutHeroSloganKeywordElements(track);
392	    const y = -(keywordHeight * step);
393	    if (!shouldAnimate || !gsap) {
394	      track.style.transform = `translate3d(0, ${y}px, 0)`;
395	      viewport.style.width = `${keywordWidth}px`;
396	      this._applyAboutHeroSloganKeywordVisualState(keywords, step);
397	      return;
398	    }
399	    gsap.killTweensOf?.(track);
400	    gsap.killTweensOf?.(viewport);
401	    gsap.to(track, {
402	      y,
403	      duration: ABOUT_HERO_SLOGAN.duration,
404	      ease: ABOUT_HERO_SLOGAN.ease,
405	      overwrite: true,
406	    });
407	    gsap.to(viewport, {
408	      width: keywordWidth,
409	      duration: ABOUT_HERO_SLOGAN.duration,
410	      ease: ABOUT_HERO_SLOGAN.ease,
411	      overwrite: true,
412	    });
413	    this._animateAboutHeroSloganKeywordVisualState(keywords, step, gsap);
414	  }
