334	  private _applyVector3(
335	    obj: HasPositionSet,
336	    vars: ObjectVars | CameraVars,
337	    applyRotation = true,
338	  ): void {
339	    if (vars.position)
340	      obj.position.set(
341	        this._num(vars.position.x),
342	        this._num(vars.position.y),
343	        this._num(vars.position.z),
344	      );
345	    if (applyRotation && "rotation" in vars && vars.rotation && obj.rotation) {
346	      const r = Helpers.rotationDegToRad({
347	        x: this._num(vars.rotation.x),
348	        y: this._num(vars.rotation.y),
349	        z: this._num(vars.rotation.z),
350	      });
351	      obj.rotation.set(r.x, r.y, r.z);
