361	  private _isPlainRecord(obj: unknown): obj is Record<string, unknown> {
362	    if (
363	      obj == null ||
364	      typeof obj !== "object" ||
365	      Array.isArray(obj) ||
366	      obj instanceof THREE.Object3D
367	    ) {
368	      return false;
369	    }
370	    const proto = Object.getPrototypeOf(obj);
371	    return proto === Object.prototype || proto === null;
