541	  setViewport(width: number, height: number): void {
542	    const dpr = Math.min(
543	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
544	      this._pixelRatioMax,
545	    );
546	    this._camera.aspect = width / height;
547	    this._camera.updateProjectionMatrix();
