561	    this._animationLoop?.dispose();
562	    this._animationLoop = null;
563	    this._postProcessor?.dispose();
564	    this._postProcessor = null;
565	    this._backgroundManager?.dispose();
566	    this._backgroundManager = null;
567	    this._loader.dispose();
568	    if (this._cameraTarget.parent)
569	      this._cameraTarget.parent.remove(this._cameraTarget);
570	    this._cameraTargetFollow = null;
571	    this._cameraTargetFollowAnchorNode = null;
572	    this._cameraTargetFollowLocalAnchor = null;
573	    this._scene.dispose();
574	    this._detachContextEvents();
575	    this._renderer?.dispose?.();
