578	
579	  private _attachContextEvents(): void {
580	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
581	    const canvas = this._renderer.domElement;
582	    this._onContextLost = (event: Event): void => {
583	      const webglEvent = event as Event & { preventDefault?: () => void };
584	      webglEvent.preventDefault?.();
585	      this._contextLost = true;
586	      this._animationLoop?.stop();
587	    };
588	    this._onContextRestored = (): void => {
589	      this._contextLost = false;
590	      this._animationLoop?.start();
591	    };
592	    canvas.addEventListener("webglcontextlost", this._onContextLost);
593	    canvas.addEventListener("webglcontextrestored", this._onContextRestored);
594	  }
595	
596	  private _detachContextEvents(): void {
597	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
598	    const canvas = this._renderer.domElement;
599	    if (this._onContextLost) {
600	      canvas.removeEventListener("webglcontextlost", this._onContextLost);
601	    }
602	    if (this._onContextRestored) {
603	      canvas.removeEventListener(
604	        "webglcontextrestored",
605	        this._onContextRestored,
606	      );
607	    }
608	    this._onContextLost = null;
609	    this._onContextRestored = null;
610	    this._contextLost = false;
611	  }
612	
613	  private _resolveRenderBudget(
614	    options: RenderBudgetOptions | undefined,
615	  ): Required<RenderBudgetOptions> {
616	    const budgetMs =
617	      Number.isFinite(options?.budgetMs as number) &&
618	      (options?.budgetMs as number) > 0
619	        ? (options?.budgetMs as number)
620	        : DEFAULT_RENDER_BUDGET.budgetMs;
621	    const mode =
622	      options?.mode === "consistent" || options?.mode === "performance"
623	        ? options.mode
624	        : DEFAULT_RENDER_BUDGET.mode;
625	    const enterSkipFrames =
626	      Number.isFinite(options?.enterSkipFrames as number) &&
627	      (options?.enterSkipFrames as number) > 0
628	        ? Math.floor(options?.enterSkipFrames as number)
629	        : DEFAULT_RENDER_BUDGET.enterSkipFrames;
630	    const exitSkipFrames =
631	      Number.isFinite(options?.exitSkipFrames as number) &&
632	      (options?.exitSkipFrames as number) > 0
633	        ? Math.floor(options?.exitSkipFrames as number)
634	        : DEFAULT_RENDER_BUDGET.exitSkipFrames;
635	    return { budgetMs, mode, enterSkipFrames, exitSkipFrames };
636	  }
637	
638	  private _resolvePostProcessorOptions(): EngineOptions["postProcessing"] | null {
639	    const options = this._opts.postProcessing;
640	    if (!options) return null;
641	    const hasBloom = options.bloom !== false && options.bloom != null;
642	    const hasVignette = options.vignette !== false && options.vignette != null;
643	    if (!hasBloom && !hasVignette) {
644	      return null;
645	    }
646	    return options;
647	  }
648	
649	  private _resetRenderModeState(): void {
650	    this._renderModeState.skipActive = false;
651	    this._renderModeState.exceededFrames = 0;
652	    this._renderModeState.stableFrames = 0;
653	  }
654	
655	  private _shouldSkipPostProcessing(frameExceeded: boolean): boolean {
656	    if (!this._postProcessor || this._renderBudget.mode !== "performance") {
657	      this._resetRenderModeState();
658	      return false;
659	    }
660	
661	    if (frameExceeded) {
662	      this._renderModeState.exceededFrames += 1;
663	      this._renderModeState.stableFrames = 0;
664	      if (
665	        !this._renderModeState.skipActive &&
666	        this._renderModeState.exceededFrames >=
667	          this._renderBudget.enterSkipFrames
668	      ) {
669	        this._renderModeState.skipActive = true;
670	      }
671	      return this._renderModeState.skipActive;
672	    }
673	
674	    this._renderModeState.stableFrames += 1;
675	    this._renderModeState.exceededFrames = 0;
676	    if (
677	      this._renderModeState.skipActive &&
678	      this._renderModeState.stableFrames >= this._renderBudget.exitSkipFrames
679	    ) {
680	      this._renderModeState.skipActive = false;
681	    }
682	    return this._renderModeState.skipActive;
683	  }
684	
685	  private _renderMainScene(skipPostProcessing: boolean): void {
686	    if (!this._renderer) return;
687	    this._backgroundManager?.render();
688	    if (skipPostProcessing || !this._postProcessor) {
689	      this._renderer.render?.(this._scene.three, this._camera);
690	      return;
691	    }
692	    try {
693	      this._postProcessor.render(this._scene.getBloomRoots(), this._lastDelta);
694	    } catch (error) {
695	      if (!this._didWarnPostProcessingFallback) {
696	        this._didWarnPostProcessingFallback = true;
697	      }
698	      this._renderer.render?.(this._scene.three, this._camera);
699	    }
700	  }
701	
702	  private _compileScene(camera: THREE.Camera): void {
703	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
704	    this._renderer.compile(this._scene.three, camera);
705	  }
706	
707	  private _prepareTexture(texture: THREE.Texture): void {
708	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
709	    const renderer = this._renderer as THREE.WebGLRenderer & {
710	      initTexture?: (map: THREE.Texture) => void;
711	    };
712	    renderer.initTexture?.(texture);
713	  }
714	}
