502	    await this.init();
503	    this._syncFilterModalSelection(category);
504	  }
505	
506	  private readonly _handleScroll = (): void => {
507	    if (!this._feedState.hasMore) return;
508	    if (this._loading) return;
509	    const list = this._elements.gridList;
510	    if (!list) return;
511	    const thresholdReached = this._isThresholdReached(list);
512	    if (!thresholdReached) {
513	      this._thresholdArmed = true;
514	      return;
515	    }
516	    if (!this._thresholdArmed) return;
517	    this._thresholdArmed = false;
518	    void this._loadMore();
519	  };
520	
521	  private _isThresholdReached(list: HTMLElement): boolean {
522	    const rect = list.getBoundingClientRect();
523	    return (
524	      rect.bottom - window.innerHeight <= WORK_GRID_INFINITE_CONFIG.thresholdPx
525	    );
526	  }
527	
528	  private _attachSentinel(): void {
529	    this._detachSentinel();
530	    if (!this._feedState.hasMore) return;
531	    const list = this._elements.gridList;
532	    if (!list) return;
533	    const sentinel = document.createElement("div");
534	    sentinel.style.height = "1px";
535	    sentinel.setAttribute("aria-hidden", "true");
536	    list.after(sentinel);
537	    this._sentinel = sentinel;
538	    this._sentinelObserver = new IntersectionObserver(
539	      (entries) => {
540	        if (entries[0]?.isIntersecting) void this._loadMore();
541	      },
542	      { rootMargin: `${WORK_GRID_INFINITE_CONFIG.thresholdPx}px` },
543	    );
544	    this._sentinelObserver.observe(sentinel);
545	  }
546	
547	  private _detachSentinel(): void {
548	    this._sentinelObserver?.disconnect();
549	    this._sentinelObserver = null;
550	    this._sentinel?.remove();
551	    this._sentinel = null;
552	  }
553	
554	  private _bindFilterModal(): void {
