6	export class SubpageStarfieldRuntime {
7	  private _canvas: HTMLCanvasElement | null = null;
8	  private _context: CanvasRenderingContext2D | null = null;
9	  private _stars: SubpageStarfieldStar[] = [];
10	  private _width = 0;
11	  private _height = 0;
12	  private _centerX = 0;
13	  private _centerY = 0;
14	  private _rafId: number | null = null;
15	  private _pageshowListenerAttached = false;
16	  private _resizeListener: (() => void) | null = null;
17	  private _scrollListener: (() => void) | null = null;
18	  private _scrollBoost = 0;
19	  private _targetScrollBoost = 0;
20	  private _lastScrollY = 0;
21	  private _lastFrameTime = 0;
